minePage=function(){const p=state.profile8,m=recordMetrics(state.records.filter(r=>r.finished));return `<div class="m-content"><div class="m-home-title"><h1>我的</h1><span class="m-badge7">本机模型</span></div><div class="m-hero7"><div class="m-profile-head8"><div class="m-avatar8">弓</div><div><h2>${esc(p.name)}</h2><small>${esc(p.bow)} · ${esc(p.hand)} · ${esc(p.experience)}</small></div></div><button type="button" class="m-flat m-full m-spaced" data-mine8="profile">编辑训练资料</button></div><div class="m-card"><div class="m-row m-between"><h2>我的训练目标</h2><button type="button" class="m-flat" data-mine8="goals">编辑</button></div><p>${esc(p.goal)}</p><small>每周 ${esc(p.weekly)} 次 · 偏好示例，不自动生成计划</small></div><div class="m-card">${mineRow8('器材套组',state.kits.length+'套配置 · 常用器材与配件','data-open-kits')}${mineRow8('训练记录',m.sessions+'次已结束 · '+m.arrows+'箭 · 不含示例','data-mine-review8')}${mineRow8('常用偏好',esc(p.distance)+'米 · 每组默认'+esc(p.arrows)+'箭（偏好示意）','data-mine8="preferences"')}</div><div class="m-card"><h2>数据与隐私</h2>${mineRow8('记录与草稿',state.suspended.length+'份草稿 · 当前仅内存保留','data-mine8="data"')}${mineRow8('账号与同步','未连接账号 · 不上传记录','data-mine8="account"')}${mineRow8('手机权限','相机、视频、提醒与本地保存说明','data-mine8="permissions"')}${mineRow8('隐私与数据导出','用途说明 · 正式导出尚未接入','data-mine8="privacy"')}</div><div class="m-card">${mineRow8('操作帮助','录入、拖动、修改和退出保护','data-mine8="help"')}${mineRow8('关于','个人射箭训练','data-mine8="about"')}</div><p class="m-preview-note">资料和目标为可编辑样例，不代表你的真实信息。刷新清空。</p></div>`;};
