function hull9(points){const p=[...new Map(points.map(a=>[a.x+','+a.y,{x:a.x,y:a.y}])).values()].sort((a,b)=>a.x-b.x||a.y-b.y);if(p.length<3)return p;const cross=(o,a,b)=>(a.x-o.x)*(b.y-o.y)-(a.y-o.y)*(b.x-o.x),lo=[],hi=[];for(const a of p){while(lo.length>1&&cross(lo.at(-2),lo.at(-1),a)<=0)lo.pop();lo.push(a);}for(const a of [...p].reverse()){while(hi.length>1&&cross(hi.at(-2),hi.at(-1),a)<=0)hi.pop();hi.push(a);}return lo.slice(0,-1).concat(hi.slice(0,-1));}
function geometry9(arrows){const all=arrows.filter(located8),inside=all.filter(a=>a.code!=='M'),n=inside.length;if(!n)return {all,inside,n:0,hull:hull9(all),x:null,y:null,rx:null,ry:null,angle:null,rms:null};const x=inside.reduce((s,a)=>s+a.x,0)/n,y=inside.reduce((s,a)=>s+a.y,0)/n,xx=inside.reduce((s,a)=>s+(a.x-x)**2,0)/n,yy=inside.reduce((s,a)=>s+(a.y-y)**2,0)/n,xy=inside.reduce((s,a)=>s+(a.x-x)*(a.y-y),0)/n,d=Math.hypot(xx-yy,2*xy);return {all,inside,n,hull:hull9(all),x,y,rx:Math.sqrt(Math.max(0,(xx+yy+d)/2)),ry:Math.sqrt(Math.max(0,(xx+yy-d)/2)),angle:Math.atan2(2*xy,xx-yy)/2*180/Math.PI,rms:n>1?Math.sqrt(xx+yy):null};}
function outline9(points){const c=concentration(points.filter(a=>a.code!=='M'));return c&&c.count>1?`<circle data-outline9="circle" cx="${c.x}" cy="${c.y}" r="${c.radius}" fill="#16877b25" stroke="#116b67" stroke-width="2.2"/>`:'';}
function density9(points){const bins=new Map();points.forEach(a=>{const x=Math.floor((a.x-20)/20)*20+20,y=Math.floor((a.y-20)/20)*20+20,k=x+','+y;if(!bins.has(k))bins.set(k,{x,y,n:0});bins.get(k).n++;});return [...bins.values()];}
targetBoard=function(points=[]){let h=v8.targetBoard(points);if(state.photo)return h;const s=state.session,f=family(s.common.target),p=points.filter(a=>located8(a)&&(f.layout==='single'||a.face===s.face));return h.replace('</svg>',`<g pointer-events="none">${outline9(p)}</g></svg>`);};
