function cycleSheet10(){const c=state.cycle10,dates=cycleDates10(c),p=state.templates.find(p=>String(p.id)===c.planId),g=goalBy10(c.goalId);return sheet(`<h2>安排长期训练</h2><label class="m-field">可复用计划<select data-cycle10="planId">${state.templates.map(p=>`<option value="${p.id}" ${String(p.id)===c.planId?'selected':''}>${esc(p.name)} · ${totals(p).arrows}箭</option>`).join('')}</select></label><label class="m-field">关联目标（可不选）<select data-cycle10="goalId"><option value="">不关联目标</option>${state.goals10.map(g=>`<option value="${g.id}" ${g.id===c.goalId?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><label class="m-field">器材套组<select data-cycle10="kitId"><option value="">沿用计划配置</option>${state.kits.map(k=>`<option value="${k.id}" ${k.id===c.kitId?'selected':''}>${esc(k.name)}</option>`).join('')}</select></label><div class="m-pair10">${[['start','从'],['end','到']].map(([k,t])=>`<label class="m-field">${t}<input type="date" data-cycle10="${k}" value="${c[k]}"></label>`).join('')}</div><label class="m-field">重复方式<select data-cycle10="mode"><option value="weekly" ${c.mode==='weekly'?'selected':''}>每周指定日</option><option value="monthly" ${c.mode==='monthly'?'selected':''}>每月指定日</option></select></label>${c.mode==='weekly'?`<div class="m-week10">${[1,2,3,4,5,6,0].map((v,i)=>`<button type="button" data-weekday10="${v}" aria-pressed="${c.weekdays.includes(v)}">${['一','二','三','四','五','六','日'][i]}</button>`).join('')}</div>`:`<label class="m-field">每月几号<input type="number" min="1" max="31" data-cycle10="monthDay" value="${c.monthDay}"></label><small>该月没有此日期则跳过，不挪到下个月。</small>`}<p class="m-note10">${dates?`将安排 ${dates.length} 次 · ${dates.length*(p?totals(p).arrows:0)} 箭`:'请选择从今天起、最长366天的有效范围。'}${g?`<br/>目标日期：${g.start} 至 ${g.end}`:''}</p>${dates?.length?`<details><summary>预览安排日期</summary><p class="m-small">${dates.map(d=>d.slice(5)).join('、')}</p></details>`:''}<p class="m-feedback" role="alert">${esc(state.notice)}</p><div class="m-row m-spaced"><button type="button" class="m-grow" data-close-overlay>取消</button><button type="button" class="m-primary m-grow" data-cycle-save10 ${!dates?.length?'disabled':''}>确认加入日历</button></div><p class="m-small m-spaced">安排保存独立计划快照；重复确认不会重复加入同计划同日同目标。</p>`,'长期计划编排');}
function saveCycle10(){const c=state.cycle10,dates=cycleDates10(c),p=state.templates.find(p=>String(p.id)===c.planId),g=goalBy10(c.goalId);if(!p||!dates?.length||c.mode==='monthly'&&(!Number.isInteger(Number(c.monthDay))||c.monthDay<1||c.monthDay>31)||g&&dates.some(d=>d<g.start||d>g.end)){state.notice='请检查安排日期、重复规则；关联目标时日期必须在目标范围内。';render();return false;}let added=0;for(const date of dates){if(state.schedules.some(s=>s.date===date&&s.planId===p.id&&(s.goalId10||'')===c.goalId))continue;const s=addSchedule(p.id,date);s.planSnapshot10.goalId10=c.goalId||null;s.goalId10=c.goalId||null;if(c.kitId)s.planSnapshot10.common.kitId=c.kitId;s.demo=false;added++;}state.overlay=null;state.secondary10=null;state.page='entry';state.trainMonth=c.start.slice(0,7);state.trainDay=c.start;state.notice=`已加入${added}次安排，既有相同安排未重复添加`;render();return added;}
function nextSheet10(){const n=state.next10,options=state.schedules.filter(canChangeSchedule10);return sheet(`<h2>把复盘带到下一次</h2><p class="m-small">来源：${esc(n.record.name)}${n.record.demo?'（示例）':''}。保留原记录，调整未来安排。</p><label class="m-field">下次训练重点<textarea data-next10="focus" rows="3">${esc(n.focus)}</textarea></label><label class="m-field">安排方式<select data-next10="scheduleId"><option value="">创建新计划副本并安排</option>${options.map(s=>`<option value="${s.id}" ${n.scheduleId===s.id?'selected':''}>调整 ${s.date} · ${esc(planFor10(s)?.name)}</option>`).join('')}</select></label>${!n.scheduleId?`<label class="m-field">训练日期<input type="date" data-next10="date" value="${n.date}"></label>`:''}<label class="m-field">关联目标<select data-next10="goalId"><option value="">不关联目标</option>${state.goals10.map(g=>`<option value="${g.id}" ${n.goalId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><p class="m-feedback" role="alert">${esc(state.notice)}</p><div class="m-row"><button type="button" class="m-grow" data-close-overlay>取消</button><button type="button" class="m-primary m-grow" data-next-build10>确认重点，检查计划</button></div>`,'复盘转计划');}
function buildNext10(){const n=state.next10,s=n.scheduleId?state.schedules.find(s=>s.id===n.scheduleId):null,date=s?s.date:n.date,g=goalBy10(n.goalId);if(!dateValid8(date)||date<todayKey||n.scheduleId&&!canChangeSchedule10(s)||g&&(date<g.start||date>g.end)){state.notice='只能调整未开始的未来安排，日期须位于所选目标范围内。';render();return false;}let p=s?clone(planFor10(s)):n.record.plan?clone(n.record.plan):{id:null,name:n.record.name,common:clone(n.record.common),lanes:[{id:'first',blocks:n.record.ends.filter(e=>e.phase!=='second').map(e=>scoreBlock(1,e.arrows.length))},{id:'second',blocks:n.record.ends.filter(e=>e.phase==='second').map(e=>scoreBlock(1,e.arrows.length))}]};p.id=null;p.name=p.name+' · 下次重点';p.goalId10=n.goalId||null;p.sourceRecord10=n.record.id;for(const b of allBlocks(p)){b.id=uid++;if(b.type==='score')b.focus=n.focus;}state.pendingNext10={date,scheduleId:n.scheduleId};state.overlay=null;state.secondary10=null;beginDraft(p);state.draft.id=null;state.notice='请核对距离、靶面、器材和训练量；保存后才更新未来日历。';render();return true;}
savePlan=function(){const pending=state.pendingNext10,g=goalBy10(state.draft?.goalId10);if(pending&&g&&(pending.date<g.start||pending.date>g.end)){state.notice='安排日期不在新选目标范围内，请更换目标后保存。';render();return false;}if(pending?.scheduleId&&!canChangeSchedule10(state.schedules.find(s=>s.id===pending.scheduleId))){state.notice='原安排已开始，未覆盖。请返回复盘创建新的未来安排。';render();return false;}if(!v10.savePlan())return false;if(pending){const p=state.templates.find(p=>p.id===state.draft.id);if(pending.scheduleId){const s=state.schedules.find(s=>s.id===pending.scheduleId);s.planId=p.id;s.planSnapshot10=clone(p);s.plannedArrows10=totals(p).arrows;s.goalId10=p.goalId10||null;}else addSchedule(p.id,pending.date);state.pendingNext10=null;}return true;};
setup=function(){return v10.setup().replace('<button type="button" class="m-primary m-full" data-to-builder>',`<label class="m-field">关联训练目标<select data-plan-goal10><option value="">不关联目标</option>${state.goals10.map(g=>`<option value="${g.id}" ${state.draft.goalId10===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><button type="button" class="m-primary m-full" data-to-builder>`);};
function observationSheet10(){const o=state.obsDraft10;return sheet(`<h2>${o.index==null?'练后':'第'+(o.index+1)+'组'}体能自评（可选）</h2><label class="m-field">主观疲劳<select data-observation10="score"><option value="">未填写</option>${Array.from({length:11},(_,i)=>`<option value="${i}" ${String(o.score)===String(i)?'selected':''}>${i}${i===0?' · 不疲劳':i===10?' · 极疲劳':''}</option>`).join('')}</select></label><label class="m-field">感受或当时情况<textarea data-observation10="note" maxlength="500" rows="3">${esc(o.note)}</textarea></label><p class="m-small">本人主观填写，不是医学量表。仅与训练表现并列观察，不自动诊断疲劳原因或调整训练量。</p><div class="m-row"><button type="button" class="m-grow" data-close-overlay>取消</button><button type="button" class="m-primary m-grow" data-observation-save10>保存自评</button></div>`,'体能观察');}
function beginObservation10(index=null){const r=currentRecord(),e=index==null?null:r.ends[index];state.obsDraft10={record:r,index,score:index==null?r.observation10?.after??'':e.fatigue10??'',note:index==null?r.observation10?.note||'':e.fatigueNote10||''};state.overlay='observation10';render();}
