function fatiguePanel10(r){return `<div class="m-card"><div class="m-row m-between"><h2>体能与疲劳观察</h2><button type="button" class="m-flat" data-observation10-open="session">练后自评</button></div><p class="m-small">练后自评：${r.observation10?.after==null?'未填写':r.observation10.after+'／10'}${r.demo?' · 示例':''}</p>${r.ends.map((e,i)=>`<button type="button" class="m-list-button" data-observation10-open="${i}"><span><strong>第${e.number}组</strong><small>平均${fmt8(stats8(e.arrows).mean)}环 · 已定位${e.arrows.filter(located8).length}／${e.arrows.length}箭</small></span><span><strong>${e.fatigue10==null?'未填':e.fatigue10+'／10'}</strong><small>点选补记</small></span></button>`).join('')}<p class="m-small m-spaced">自评与分数、散布、组间录入间隔可对照，但不能把变化自动归因为体能。未填写不补零。</p></div>`;}
