function scoringDiameter10(r){const f=rules8(r),size=r.common.size;if(!Number.isFinite(size)||size<=0)return null;if(f.custom)return size;if(f.id==='full'&&[40,60,80,122].includes(size))return size;if(f.id==='six'&&size===80)return 48;if(['vertical','triangle'].includes(f.id)&&size===40)return 20;return null;}
