function faceArrows10(r,arrows){return state.face10==='all'?arrows:state.face10==='unknown'?arrows.filter(a=>![1,2,3].includes(a.face)):arrows.filter(a=>a.face===Number(state.face10));}
function facePanel10(r,arrows){const f=rules8(r),g=geometry9(faceArrows10(r,arrows)),d=scoringDiameter10(r);return `<div class="m-card"><h2>${f.layout==='single'?'实际尺寸与散布':'分靶位分析'}</h2>${f.layout!=='single'?`<div class="m-shape9">${[['all','靶心对齐叠加'],['1','靶1'],['2','靶2'],['3','靶3'],['unknown','未分配']].map(([v,t])=>`<button type="button" data-face10="${v}" aria-pressed="${state.face10===v}">${t}</button>`).join('')}</div>${plot9(faceArrows10(r,arrows),f,'outline')}<div class="m-pair10">${[1,2,3].map(i=>{const a=arrows.filter(a=>a.face===i);return `<div><small>靶${i}</small><strong>${a.length}箭</strong><small>平均${fmt8(stats8(a).mean)}环</small></div>`;}).join('')}</div><p class="m-small m-spaced">未分配靶位 ${arrows.filter(a=>![1,2,3].includes(a.face)).length} 箭，不凭坐标猜所属靶。对齐叠加不是靶纸上实际位置。</p>`:''}<div class="m-pair10"><div><small>靶内中心偏移</small><strong>${length10(g.n?Math.hypot(g.x-120,g.y-120):null,r)}</strong></div><div><small>靶内散布 RMS</small><strong>${length10(g.rms,r)}</strong></div></div><p class="m-small m-spaced">${d!=null?`按实际计分外径 ${d} cm 换算${f.custom?'（自建尺寸由用户填写）':''}。标称尺寸 ${r.common.size} cm；来自点选坐标，不代表实物测量精度。`:'尺寸未知或变体尺寸含义未核准，只展示相对计分半径，不换算厘米。'}M不进入靶内指标。</p><button type="button" class="m-flat m-full" data-triple-example10>查看三联分靶位独立示例</button></div>`;}
function bucket10(records,grain){const map=new Map();for(const r of [...records].sort((a,b)=>recordDay(a).localeCompare(recordDay(b)))){const date=recordDay(r),key=grain==='session'?String(r.id):grain==='week'?weekStart10(date):grain==='month'?date.slice(0,7):date;if(!map.has(key))map.set(key,{key,label:grain==='month'?key:grain==='session'?date.slice(5):key.slice(5),records:[]});map.get(key).records.push(r);}return [...map.values()].map(p=>{const a=p.records.flatMap(allArrows),m=stats8(a),g=geometry9(a),f=rules8(p.records[0]);return {...p,n:a.length,geometry:g,stats:m,rates:{yellow:f.custom?null:m.n?(m.counts.X+m.counts['10']+m.counts['9'])/m.n*100:null,x:!f.x?null:m.n?m.counts.X/m.n*100:null,ten:m.n?m.counts['10']/m.n*100:null,miss:m.n?m.counts.M/m.n*100:null},dx:g.n?g.x-120:null,dy:g.n?120-g.y:null,rms:g.rms};});}
function metricChart10(points,key,label,unit,signed=false){const list=points.slice(-12),w=Math.max(220,(screen.clientWidth||362)-58),h=176,left=64,right=w-20,top=27,bottom=126,values=list.map(p=>p[key]).filter(Number.isFinite),min=signed?Math.min(0,...values):-0,max0=Math.max(0,...values),span=Math.max(1,max0-min),lo=signed?min-span*.12:0,hi=max0+span*.12,x=i=>list.length<=1?(left+right)/2:left+i*(right-left)/(list.length-1),y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);if(!values.length)return `<p class="m-empty7">${esc(label)}：没有可用数据，不填零。</p>`;return `<svg class="m-metric-chart10" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}，${esc(unit)}"><text x="0" y="14" fill="currentColor" font-size="13">${esc(unit)}</text>${[lo,(lo+hi)/2,hi].map(v=>`<line x1="${left}" x2="${right}" y1="${y(v)}" y2="${y(v)}" stroke="var(--m-line)"/><text x="${left-7}" y="${y(v)+4}" text-anchor="end" font-size="12" fill="var(--m-sub)">${v.toFixed(1)}</text>`).join('')}${list.map((p,i)=>p[key]==null?'':`${i&&list[i-1][key]!=null?`<line x1="${x(i-1)}" y1="${y(list[i-1][key])}" x2="${x(i)}" y2="${y(p[key])}" stroke="var(--m-accent)" stroke-width="2"/>`:''}<circle cx="${x(i)}" cy="${y(p[key])}" r="4" fill="var(--m-accent)"/>${list.length<=4||i===0||i===list.length-1?`<text x="${x(i)}" y="${y(p[key])-8}" text-anchor="middle" font-size="12" fill="currentColor">${p[key].toFixed(1)}</text>`:''}`).join('')}${list.map((p,i)=>list.length<=4||i===0||i===list.length-1?`<text x="${x(i)}" y="151" text-anchor="middle" font-size="12" fill="var(--m-sub)">${esc(p.label)}</text>`:'').join('')}<text x="${right}" y="174" text-anchor="end" fill="var(--m-sub)" font-size="12">${state.analysisGrain10==='week'?'周起始日（周一）':state.analysisGrain10==='month'?'月份':'日期'}</text></svg>`;}
function analysisRecords10(){const records=filtered8();return state.analysisCondition10?records.filter(r=>conditionKey8(r)===state.analysisCondition10):records;}
function analysisReady10(records){return records.length>0&&new Set(records.map(conditionKey8)).size===1;}
