function equipmentCompare10(records){const groups=kitBuckets10(records).filter(g=>g.key!=='unknown');if(!groups.some(g=>g.key===state.kitA10))state.kitA10=groups[0]?.key||'';if(!groups.some(g=>g.key===state.kitB10))state.kitB10=groups[1]?.key||'';const a=groups.find(g=>g.key===state.kitA10),b=groups.find(g=>g.key===state.kitB10);return `<div class="m-card"><h2>器材快照对照</h2><p class="m-small">同一器材修改配置后视为不同快照；不会把后来配置套回旧记录。</p>${['A','B'].map(k=>`<label class="m-field">配置 ${k}<select data-kit-compare10="${k}"><option value="">请选择配置</option>${groups.map((g,i)=>`<option value="${esc(g.key)}" ${state['kit'+k+'10']===g.key?'selected':''}>${esc(g.label)} · 快照${i+1} · ${g.records.length}次</option>`).join('')}</select></label>`).join('')}${!a||!b?'<p class="m-empty7">当前条件下需要两种已记录器材快照。缺器材记录的训练不推定属于某套组。</p>':a.key===b.key?'<p class="m-caution">请选择不同器材快照。</p>':`${comparePanel8(a.records.flatMap(allArrows),b.records.flatMap(allArrows),'配置 A','配置 B')}<div class="m-pair10">${[a,b].map(g=>{const geo=geometry9(g.records.flatMap(allArrows));return `<div><small>靶内已定位${geo.n}箭</small><strong>${geo.rms==null?'—':geo.rms.toFixed(1)+'%'}</strong><small>靶内RMS／计分半径</small></div>`;}).join('')}</div>`}<p class="m-small m-spaced">同条件筛选仍不能排除训练日期、状态等差异；只描述样本，不归因为器材，也不推荐购买。</p></div>`;}
function analyticsPage10(){state.pointRecords9=[];const all=filtered8(),options=[...new Map(all.map(r=>[conditionKey8(r),condition(r.common)+' · '+(r.common.bow||'弓种未知')])).entries()],records=analysisRecords10(),ready=analysisReady10(records),b=bucket10(records,state.analysisGrain10);return `<div class="m-content"><button type="button" class="m-flat" data-secondary10="">‹ 返回复盘</button><h1>长期分析</h1><p class="m-source10">${state.reviewSource==='demo'?'示例数据':'本次试录'} · ${esc(timeLabel9())} · ${esc(conditionsLabel9())}</p><label class="m-field">本页比较配置<select data-analysis-condition10><option value="">全部已筛选配置</option>${options.map(([k,v])=>`<option value="${esc(k)}" ${state.analysisCondition10===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="m-grain9">汇总单位<select data-analysis-grain10>${[['day','按日'],['week','按周'],['month','按月']].map(([v,t])=>`<option value="${v}" ${state.analysisGrain10===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="m-analysis-nav10">${[['geometry','偏向散布'],['rates','各环比例'],['equipment','器材对照']].map(([k,t])=>`<button type="button" data-analysis-tab10="${k}" aria-pressed="${state.analysisTab10===k}">${t}</button>`).join('')}</div>${!ready?'<p class="m-caution">请选一个有记录的配置；不同靶型、距离、尺寸和弓种不合并成同条件分析。</p>':state.analysisTab10==='equipment'?equipmentCompare10(records):state.analysisTab10==='rates'?`<p class="m-small">各项分母均为该时段实际箭数（含M）；X和普通10分别计数。自建靶不强套标准黄心率，未设X的靶型不虚构X率。</p>${[['yellow','黄心率 X＋10＋9'],['x','X率'],['ten','普通10率（不含X）'],['miss','脱靶率 M']].map(([k,t])=>`<div class="m-card"><h2>${t}</h2>${metricChart10(b.map(p=>({...p,rate:p.rates[k]})),'rate',t,'%')}</div>`).join('')}`:`<p class="m-small">按原始靶内已定位点重新汇总，不平均每组RMS。M只显示在全点范围；未知条件不等于已确认相同。</p>${[['dx','水平偏向（右正／左负）',true],['dy','垂直偏向（上正／下负）',true],['rms','靶内散布 RMS',false]].map(([k,t,signed])=>`<div class="m-card"><h2>${t}</h2>${metricChart10(b,k,t,'计分半径 %',signed)}</div>`).join('')}`}${ready?`<div class="m-card"><h2>本页数据依据</h2>${b.slice(-12).map(p=>{const i=state.pointRecords9.push(p)-1;return `<button type="button" class="m-list-button" data-point9="${i}"><span><strong>${p.label}</strong><small>${p.records.length}次 · ${p.n}箭 · 有坐标${p.geometry.all.length}箭</small></span><span><small>靶内坐标${p.geometry.n}箭<br/>查看原始记录 ›</small></span></button>`;}).join('')}<p class="m-small">${b.length>12?'图表仅显示最近12个有记录时段。':''}没有训练的日期不补零；没有坐标的箭不参与偏向和散布。</p></div>`:''}</div>`;}
const capability10={save:{title:'记录保存与恢复',body:'位置示意：自动保存、关闭后恢复、离线队列和云同步。当前记录只在预览内存中，刷新会清空。',actions:['自动保存：未接入','恢复历史：未接入','离线队列：未接入','云同步：未连接']},account:{title:'账号与数据管理',body:'位置示意：真实登录、账号管理、导入导出与删除。这里不收集账号或密码，也不会删除真实数据。',actions:['登录／注册：未接入','账号管理：未接入','导入／导出：未接入','删除记录／账号：未接入']},permissions:{title:'手机权限',body:'位置示意：相机、视频、本地存储。由用户在使用时选择，当前模型不申请系统权限。',actions:['拍摄靶面：未接入','录制视频：未接入','本地保存：未接入']},reminder:{title:'锁屏与后台提醒',body:'位置示意：休息到时提醒。本轮只有页面内计时；这里不调用系统闹钟，不承诺后台或锁屏准时提醒。',actions:['系统通知：未接入','锁屏／后台提醒：未接入']},vision:{title:'图像结果写入训练',body:'位置示意：识别候选 → 人工核对与修正 → 确认当前组 → 写入正式记录。当前拍照演示不是C专项的实际输出，不能写入正式成绩。',actions:['候选来源：演示占位','确认写入正式训练：未接入']},video:{title:'视频教练',body:'独立专项由总控审核推进。预留：拍摄／导入 → 动作观察 → 复盘报告。此处不播放示例冒充分析，不申请视频权限。',actions:['拍摄／导入：入口示意','动作报告：等待独立专项验收']}};
