function exportPage10(){const r=currentRecord(),indices=state.focusEnd9==null?r.ends.map((_,i)=>i):[state.focusEnd9],a=indices.flatMap(i=>r.ends[i].arrows),m=stats8(a),o=state.share10;return `<div class="m-content"><button type="button" class="m-flat" data-secondary10="">‹ 返回复盘</button><h1>报告分享预览</h1><p class="m-small">仅预览排版，不生成下载文件、不上传、不调用分享。</p><div class="m-checks10">${[['scores','成绩概览'],['arrows','逐箭明细'],['geometry','散布图'],['name','个人昵称'],['gear','器材详情'],['notes','练后心得']].map(([k,t])=>`<label><input type="checkbox" data-share10="${k}" ${o[k]?'checked':''}>${t}</label>`).join('')}</div><article class="m-export10" aria-label="待分享报告预览"><small>射箭训练报告 · ${r.demo?'示例':'本次试录'}</small><h2>${state.focusEnd9==null?'本次训练':'第'+(state.focusEnd9+1)+'组'}复盘</h2><p>${recordDay(r)} · ${condition(r.common)}</p>${o.name?`<p>昵称：${esc(state.profile8.name)}</p>`:'<small>个人昵称已隐藏</small>'}${o.scores?`<h2>${m.total}分 · ${m.n}箭</h2><p>平均 ${fmt8(m.mean)} 环 · X ${m.counts.X}／普通10 ${m.counts['10']}／M ${m.counts.M}</p>`:''}${o.arrows?indices.map(i=>`<div class="m-row10"><span>第${r.ends[i].number}组<small>${r.ends[i].arrows.map(a=>esc(a.code)).join('　')}</small></span><strong>${sum(r.ends[i].arrows)}分</strong></div>`).join(''):''}${o.geometry?`<h2>已知落点</h2>${plot9(a,rules8(r),'outline')}<small>已定位${a.filter(located8).length}／${a.length}箭；M显示但不计靶内散布。</small>`:''}${o.gear?`<h2>训练时器材</h2><p>${esc(r.kitSnapshot?.name||'未记录')}</p>${r.kitSnapshot?Object.entries(r.kitSnapshot.parts||{}).filter(([,v])=>v.model).map(([k,v])=>`<p class="m-small">${esc(kitParts.find(p=>p[0]===k)?.[1]||k)}：${esc(v.model)}</p>`).join(''):''}`:''}${o.notes?`<h2>练后心得</h2><p>${esc(r.reflection||'未填写')}</p>`:''}<p class="m-source10">仅描述已记录样本；不代表AI诊断。${r.demo?'合成示例，不是个人成绩。':''}</p></article><div class="m-row m-spaced"><button type="button" class="m-grow" disabled>导出图片 · 未接入</button><button type="button" class="m-grow" disabled>系统分享 · 未接入</button></div></div>`;}
